import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.XXezeKOl.js";const c=JSON.parse('{"title":"术语表","description":"AI Agent 开发常用术语的中英文对照与简明解释，按主题分组，并链接到详细讲解的文章。","frontmatter":{"title":"术语表","description":"AI Agent 开发常用术语的中英文对照与简明解释，按主题分组，并链接到详细讲解的文章。"},"headers":[],"relativePath":"glossary.md","filePath":"glossary.md","lastUpdated":null}'),o={name:"glossary.md"};function i(n,t,h,g,l,u){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><p>本页收录 Agent 开发中常见的术语，按主题分组。每个术语给出英文 / 中文名称、简要解释，以及详细讲解它的文章。</p><h2 id="基础概念" tabindex="-1">基础概念 <a class="header-anchor" href="#基础概念" aria-label="Permalink to &quot;基础概念&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>解释</th><th>相关文章</th></tr></thead><tbody><tr><td>Agent / 智能体</td><td>由大模型驱动、能根据目标自主决定下一步行动、调用工具并循环执行直到完成任务的系统。</td><td><a href="/guide/00-intro/what-is-agent">Agent 到底是什么</a></td></tr><tr><td>Workflow / 工作流</td><td>由开发者预先定义执行路径的流程，模型只在固定节点完成子任务，路径不由模型决定。</td><td><a href="/guide/00-intro/agent-vs-workflow">Agent、Chatbot 与 Workflow 的区别</a></td></tr><tr><td>Chatbot / 聊天机器人</td><td>以一问一答的对话为主要形式的应用，通常只生成文本，不主动执行动作。</td><td><a href="/guide/00-intro/agent-vs-workflow">Agent、Chatbot 与 Workflow 的区别</a></td></tr><tr><td>Agentic / 智能体化的</td><td>形容系统具有自主决策、调用工具、多步执行的特性，比如 Agentic RAG。</td><td><a href="/guide/00-intro/capabilities">Agent 的能力边界与适用场景</a></td></tr><tr><td>LLM (Large Language Model) / 大语言模型</td><td>在海量文本上训练、能够理解和生成自然语言的大规模神经网络模型。</td><td><a href="/guide/02-llm-basics/transformer">Transformer 的直觉理解</a></td></tr></tbody></table><h2 id="大模型原理" tabindex="-1">大模型原理 <a class="header-anchor" href="#大模型原理" aria-label="Permalink to &quot;大模型原理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>解释</th><th>相关文章</th></tr></thead><tbody><tr><td>Transformer</td><td>当前大模型的主流神经网络架构，核心是注意力机制，能并行处理序列并建模长距离依赖。</td><td><a href="/guide/02-llm-basics/transformer">Transformer 的直觉理解</a></td></tr><tr><td>Attention / 注意力机制</td><td>让模型在处理每个 Token 时，按相关程度加权关注序列中的其他 Token。</td><td><a href="/guide/02-llm-basics/transformer">Transformer 的直觉理解</a></td></tr><tr><td>Token / 词元</td><td>模型处理文本的基本单位，可能是一个词、子词或字符；上下文长度、计费都按 Token 计算。</td><td><a href="/guide/02-llm-basics/tokens-context">Token 与上下文窗口</a></td></tr><tr><td>Tokenizer / 分词器</td><td>把文本切分成 Token 并映射成数字 ID 的组件，不同模型的分词器不同。</td><td><a href="/guide/02-llm-basics/tokens-context">Token 与上下文窗口</a></td></tr><tr><td>Context Window / 上下文窗口</td><td>模型单次请求能处理的最大 Token 数，包括输入和输出。</td><td><a href="/guide/02-llm-basics/tokens-context">Token 与上下文窗口</a></td></tr><tr><td>Temperature / 温度</td><td>控制采样随机性的参数，越低输出越确定，越高越多样。</td><td><a href="/guide/02-llm-basics/sampling">采样参数：temperature、top_p</a></td></tr><tr><td>Top-p / 核采样</td><td>只在累计概率达到 p 的候选 Token 中采样，截掉低概率的长尾。</td><td><a href="/guide/02-llm-basics/sampling">采样参数：temperature、top_p</a></td></tr><tr><td>Embedding / 嵌入向量</td><td>把文本等内容映射成固定长度的稠密向量，语义相近的内容向量距离更近。</td><td><a href="/guide/02-llm-basics/embeddings">Embedding 与向量语义</a></td></tr><tr><td>Reasoning Model / 推理模型</td><td>在给出答案前进行较长内部推理的模型，擅长数学、代码和复杂规划。</td><td><a href="/guide/02-llm-basics/reasoning-models">推理模型与扩展思考</a></td></tr><tr><td>Extended Thinking / 扩展思考</td><td>让模型在回答前花更多 Token 进行推理的能力或模式，通常可以设置思考预算。</td><td><a href="/guide/02-llm-basics/reasoning-models">推理模型与扩展思考</a></td></tr><tr><td>Hallucination / 幻觉</td><td>模型生成看似合理但与事实不符或无依据的内容。</td><td><a href="/guide/00-intro/capabilities">Agent 的能力边界与适用场景</a></td></tr><tr><td>Fine-tuning / 微调</td><td>在预训练模型的基础上用特定数据继续训练，改变模型的行为或能力。</td><td><a href="/guide/02-llm-basics/choosing-models">如何选择模型</a></td></tr><tr><td>Multimodal / 多模态</td><td>模型能处理文本以外的输入或输出，比如图片、音频、文档。</td><td><a href="/guide/03-llm-api/multimodal">多模态输入：图片与文档</a></td></tr></tbody></table><h2 id="大模型-api" tabindex="-1">大模型 API <a class="header-anchor" href="#大模型-api" aria-label="Permalink to &quot;大模型 API&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>解释</th><th>相关文章</th></tr></thead><tbody><tr><td>Message / 消息</td><td>对话 API 的基本单位，由角色和内容组成，多轮对话就是消息列表。</td><td><a href="/guide/03-llm-api/multi-turn">多轮对话与消息结构</a></td></tr><tr><td>Role / 角色</td><td>消息的发送方类型，常见的有 system、user、assistant，以及工具结果。</td><td><a href="/guide/03-llm-api/multi-turn">多轮对话与消息结构</a></td></tr><tr><td>Streaming / 流式输出</td><td>模型边生成边返回结果，降低用户感知的等待时间。</td><td><a href="/guide/03-llm-api/streaming">流式响应实战</a></td></tr><tr><td>SSE (Server-Sent Events) / 服务端推送事件</td><td>基于 HTTP 的单向服务端推送协议，大多数模型 API 用它实现流式输出。</td><td><a href="/guide/01-programming/streaming-sse">流式输出与 SSE</a></td></tr><tr><td>Rate Limit / 限流</td><td>模型服务对请求频率或 Token 用量的限制，超出时通常返回 429 错误。</td><td><a href="/guide/03-llm-api/cost-errors">计费、限流与错误重试</a></td></tr><tr><td>Exponential Backoff / 指数退避</td><td>失败后等待时间按指数增长再重试的策略，通常配合随机抖动。</td><td><a href="/guide/03-llm-api/cost-errors">计费、限流与错误重试</a></td></tr><tr><td>TTFT (Time To First Token) / 首 Token 延迟</td><td>从发出请求到收到第一个输出 Token 的时间，是流式体验的关键指标。</td><td><a href="/guide/15-production/cost-optimization">成本与延迟优化</a></td></tr></tbody></table><h2 id="提示词工程" tabindex="-1">提示词工程 <a class="header-anchor" href="#提示词工程" aria-label="Permalink to &quot;提示词工程&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>解释</th><th>相关文章</th></tr></thead><tbody><tr><td>Prompt / 提示词</td><td>发送给模型的输入文本，包含指令、背景、示例和数据。</td><td><a href="/guide/04-prompt/basics">提示词基本原则</a></td></tr><tr><td>System Prompt / 系统提示词</td><td>设定模型角色、规则和全局约束的消息，在整个对话中持续生效。</td><td><a href="/guide/04-prompt/system-prompt">系统提示词与角色设计</a></td></tr><tr><td>Zero-shot / 零样本</td><td>不提供示例，只用指令让模型完成任务。</td><td><a href="/guide/04-prompt/few-shot-cot">Few-shot 与思维链</a></td></tr><tr><td>Few-shot / 少样本</td><td>在提示词中提供少量输入输出示例，让模型模仿完成任务。</td><td><a href="/guide/04-prompt/few-shot-cot">Few-shot 与思维链</a></td></tr><tr><td>CoT (Chain-of-Thought) / 思维链</td><td>让模型先写出推理步骤再给出答案的方法，能提升多步推理能力。</td><td><a href="/papers/chain-of-thought">Chain-of-Thought</a></td></tr><tr><td>ToT (Tree of Thoughts) / 思维树</td><td>把推理过程扩展成可以探索、评估和回溯的树搜索。</td><td><a href="/papers/tree-of-thoughts">Tree of Thoughts</a></td></tr><tr><td>Structured Output / 结构化输出</td><td>让模型按指定格式（通常是 JSON Schema）输出，便于程序解析。</td><td><a href="/guide/04-prompt/structured-output">结构化输出与 JSON Schema</a></td></tr><tr><td>JSON Schema</td><td>描述 JSON 数据结构和约束的标准，用于定义工具参数和结构化输出格式。</td><td><a href="/guide/04-prompt/structured-output">结构化输出与 JSON Schema</a></td></tr><tr><td>Prompt Template / 提示词模板</td><td>带有变量占位符的提示词，运行时填入具体内容。</td><td><a href="/guide/04-prompt/prompt-management">提示词版本管理与测试</a></td></tr></tbody></table><h2 id="tool-calling-与-agent-循环" tabindex="-1">Tool Calling 与 Agent 循环 <a class="header-anchor" href="#tool-calling-与-agent-循环" aria-label="Permalink to &quot;Tool Calling 与 Agent 循环&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>解释</th><th>相关文章</th></tr></thead><tbody><tr><td>Tool Calling / Function Calling / 工具调用</td><td>模型生成&quot;调用哪个工具、传什么参数&quot;的结构化请求，由应用代码执行后把结果返回给模型。</td><td><a href="/guide/05-tool-calling/concept">工具调用原理</a></td></tr><tr><td>Tool Schema / 工具定义</td><td>描述工具名称、用途和参数结构的定义，是模型选择和使用工具的依据。</td><td><a href="/guide/05-tool-calling/first-tool">实现第一个工具</a></td></tr><tr><td>Parallel Tool Calls / 并行工具调用</td><td>模型在一次回复中请求多个互不依赖的工具调用，应用可以并发执行。</td><td><a href="/guide/05-tool-calling/parallel-tools">并行工具调用</a></td></tr><tr><td>Idempotency / 幂等性</td><td>同一操作执行多次与执行一次的效果相同，是工具安全重试的前提。</td><td><a href="/guide/05-tool-calling/error-handling">工具错误处理与重试</a></td></tr><tr><td>Agent Loop / Agent 循环</td><td>调用模型、执行工具、把结果放回上下文、再次调用模型，直到满足终止条件的主循环。</td><td><a href="/guide/06-agent-loop/handwritten-agent">不用框架手写 Agent</a></td></tr><tr><td>ReAct (Reasoning + Acting)</td><td>推理与行动交替进行的 Agent 模式：Thought、Action、Observation 循环。</td><td><a href="/guide/06-agent-loop/react">ReAct：推理与行动</a></td></tr><tr><td>Observation / 观察结果</td><td>Agent 执行行动后从环境或工具获得的返回信息。</td><td><a href="/guide/06-agent-loop/react">ReAct：推理与行动</a></td></tr><tr><td>Plan-and-Execute / 规划与执行</td><td>先生成完整计划，再逐步执行，必要时重新规划的 Agent 模式。</td><td><a href="/guide/06-agent-loop/plan-execute">Plan-and-Execute</a></td></tr><tr><td>Reflection / 自我反思</td><td>让模型检查和评价自己的输出或失败轨迹，再据此改进。</td><td><a href="/guide/06-agent-loop/reflection">Reflection 自我反思</a></td></tr><tr><td>Budget / 预算控制</td><td>对 Agent 的步数、Token、时间和金额设置上限，防止循环和成本失控。</td><td><a href="/guide/06-agent-loop/stop-budget">终止条件、步数与预算控制</a></td></tr></tbody></table><h2 id="上下文工程与记忆" tabindex="-1">上下文工程与记忆 <a class="header-anchor" href="#上下文工程与记忆" aria-label="Permalink to &quot;上下文工程与记忆&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>解释</th><th>相关文章</th></tr></thead><tbody><tr><td>Context Engineering / 上下文工程</td><td>设计每次模型调用时上下文中放什么、怎么放、放多少的工程实践。</td><td><a href="/guide/07-context-engineering/overview">什么是上下文工程</a></td></tr><tr><td>Sliding Window / 滑动窗口</td><td>只保留最近若干轮对话的上下文管理策略。</td><td><a href="/guide/07-context-engineering/window-management">上下文窗口管理</a></td></tr><tr><td>Compaction / 上下文压缩</td><td>把较早的对话或工具结果总结成摘要，减少上下文占用。</td><td><a href="/guide/07-context-engineering/compression">压缩与摘要</a></td></tr><tr><td>Prompt Caching / 提示词缓存</td><td>模型服务端对重复的请求前缀做缓存，降低延迟和成本。</td><td><a href="/guide/07-context-engineering/prompt-caching">Prompt Caching</a></td></tr><tr><td>Short-term Memory / 短期记忆</td><td>当前会话中的对话和任务状态，存在于上下文窗口中。</td><td><a href="/guide/08-memory/short-term">短期记忆与会话管理</a></td></tr><tr><td>Long-term Memory / 长期记忆</td><td>跨会话持久保存的信息，如用户偏好、历史经验，需要时检索。</td><td><a href="/guide/08-memory/long-term">长期记忆与用户画像</a></td></tr><tr><td>Episodic Memory / 情景记忆</td><td>记录过去发生的具体事件和经历的记忆。</td><td><a href="/guide/08-memory/memory-types">记忆的分类</a></td></tr><tr><td>Semantic Memory / 语义记忆</td><td>记录事实和知识的记忆，比如用户画像、领域知识。</td><td><a href="/guide/08-memory/memory-types">记忆的分类</a></td></tr></tbody></table><h2 id="rag-知识库" tabindex="-1">RAG 知识库 <a class="header-anchor" href="#rag-知识库" aria-label="Permalink to &quot;RAG 知识库&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>解释</th><th>相关文章</th></tr></thead><tbody><tr><td>RAG (Retrieval-Augmented Generation) / 检索增强生成</td><td>先从外部知识库检索相关内容，再结合检索结果生成答案。</td><td><a href="/guide/09-rag/overview">RAG 全景</a></td></tr><tr><td>Chunking / 切分</td><td>把文档切成适合检索的小块，块大小和边界影响检索效果。</td><td><a href="/guide/09-rag/chunking">文档解析与切分</a></td></tr><tr><td>Vector Database / 向量数据库</td><td>专门存储向量并支持高效相似度检索的数据库。</td><td><a href="/guide/09-rag/vector-db">向量数据库</a></td></tr><tr><td>ANN (Approximate Nearest Neighbor) / 近似最近邻</td><td>以少量精度损失换取速度的向量检索方法。</td><td><a href="/guide/09-rag/vector-db">向量数据库</a></td></tr><tr><td>HNSW</td><td>基于分层图结构的 ANN 索引算法，查询快、召回高，应用广泛。</td><td><a href="/guide/09-rag/vector-db">向量数据库</a></td></tr><tr><td>BM25</td><td>经典的关键词检索打分算法，擅长精确词匹配。</td><td><a href="/guide/09-rag/hybrid-rerank">混合检索与重排</a></td></tr><tr><td>Hybrid Search / 混合检索</td><td>同时使用向量检索和关键词检索，再融合结果。</td><td><a href="/guide/09-rag/hybrid-rerank">混合检索与重排</a></td></tr><tr><td>RRF (Reciprocal Rank Fusion) / 倒数排名融合</td><td>根据各路检索结果的排名融合多路结果的方法，无需分数归一化。</td><td><a href="/guide/09-rag/hybrid-rerank">混合检索与重排</a></td></tr><tr><td>Rerank / 重排</td><td>用更精确的模型对初步检索的候选重新排序。</td><td><a href="/guide/09-rag/hybrid-rerank">混合检索与重排</a></td></tr><tr><td>Cross-Encoder / 交叉编码器</td><td>把查询和文档拼接后一起输入模型打分的结构，常用作重排模型。</td><td><a href="/guide/09-rag/hybrid-rerank">混合检索与重排</a></td></tr><tr><td>Query Rewriting / 查询改写</td><td>把用户的原始问题改写成更适合检索的查询。</td><td><a href="/guide/09-rag/hybrid-rerank">混合检索与重排</a></td></tr><tr><td>GraphRAG</td><td>基于知识图谱和社区摘要进行检索增强的方法，擅长全局总结和多跳问题。</td><td><a href="/guide/09-rag/advanced-rag">GraphRAG 与 Agentic RAG</a></td></tr><tr><td>Agentic RAG</td><td>把检索作为工具交给 Agent，由 Agent 决定是否检索、检索什么、检索几次。</td><td><a href="/guide/09-rag/advanced-rag">GraphRAG 与 Agentic RAG</a></td></tr><tr><td>Faithfulness / 忠实度</td><td>衡量答案是否都有检索资料支撑、没有编造的评估指标。</td><td><a href="/guide/09-rag/rag-eval">RAG 评估</a></td></tr><tr><td>Recall@K / 前 K 召回率</td><td>相关文档出现在检索结果前 K 个中的比例。</td><td><a href="/guide/09-rag/rag-eval">RAG 评估</a></td></tr></tbody></table><h2 id="协议、框架与多-agent" tabindex="-1">协议、框架与多 Agent <a class="header-anchor" href="#协议、框架与多-agent" aria-label="Permalink to &quot;协议、框架与多 Agent&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>解释</th><th>相关文章</th></tr></thead><tbody><tr><td>MCP (Model Context Protocol) / 模型上下文协议</td><td>规定 AI 应用如何以统一方式连接外部工具和数据源的开放协议。</td><td><a href="/guide/10-mcp/mcp-overview">MCP 架构与核心概念</a></td></tr><tr><td>MCP Host / Client / Server</td><td>MCP 的三个角色：Host 是 AI 应用，Client 是其中维护单个连接的组件，Server 是暴露能力的服务。</td><td><a href="/guide/10-mcp/mcp-overview">MCP 架构与核心概念</a></td></tr><tr><td>Tools / Resources / Prompts</td><td>MCP Server 可暴露的三类能力：可调用的函数、可读取的数据、可复用的提示词模板。</td><td><a href="/guide/10-mcp/mcp-server">开发一个 MCP Server</a></td></tr><tr><td>stdio / 标准输入输出传输</td><td>MCP 的本地传输方式，Host 启动 Server 进程并通过标准输入输出通信。</td><td><a href="/guide/10-mcp/mcp-client">在应用中接入 MCP</a></td></tr><tr><td>A2A (Agent2Agent)</td><td>让不同 Agent 之间发现能力、委托任务和交换结果的协议。</td><td><a href="/guide/10-mcp/a2a">A2A：Agent 之间的协议</a></td></tr><tr><td>Agent Card</td><td>A2A 中描述一个 Agent 的身份、能力和访问方式的元数据文档。</td><td><a href="/guide/10-mcp/a2a">A2A：Agent 之间的协议</a></td></tr><tr><td>LangGraph</td><td>以图（节点和边）建模 Agent 状态流转的编排框架，支持持久化和人在环路。</td><td><a href="/guide/11-frameworks/langgraph">LangGraph</a></td></tr><tr><td>Multi-Agent System / 多 Agent 系统</td><td>由多个分工协作的 Agent 共同完成任务的系统。</td><td><a href="/guide/12-multi-agent/why-multi-agent">为什么需要多 Agent</a></td></tr><tr><td>Orchestrator-Worker / 主从模式</td><td>由一个主 Agent 分解任务、分派给多个子 Agent 执行并汇总结果的编排模式。</td><td><a href="/guide/12-multi-agent/patterns">编排模式</a></td></tr><tr><td>Handoff / 交接</td><td>一个 Agent 把对话或任务控制权转交给另一个更合适的 Agent。</td><td><a href="/guide/12-multi-agent/patterns">编排模式</a></td></tr><tr><td>Coding Agent / 编程 Agent</td><td>能阅读代码库、编写和修改代码、运行测试的 Agent。</td><td><a href="/guide/13-coding-agent/coding-agents">Coding Agent 原理</a></td></tr><tr><td>ACI (Agent-Computer Interface) / Agent-计算机接口</td><td>为 Agent 专门设计的操作界面，包括命令、反馈格式和防错机制。</td><td><a href="/papers/swe-agent">SWE-agent</a></td></tr><tr><td>Computer Use / 计算机操作</td><td>让模型通过截图、鼠标和键盘操作图形界面的能力。</td><td><a href="/guide/13-coding-agent/computer-use">Computer Use</a></td></tr><tr><td>Sandbox / 沙箱</td><td>隔离的执行环境，限制代码对宿主系统、网络和数据的访问。</td><td><a href="/guide/13-coding-agent/sandbox">沙箱与代码执行安全</a></td></tr></tbody></table><h2 id="评估与生产化" tabindex="-1">评估与生产化 <a class="header-anchor" href="#评估与生产化" aria-label="Permalink to &quot;评估与生产化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>解释</th><th>相关文章</th></tr></thead><tbody><tr><td>Eval / 评估</td><td>用一组用例和指标系统衡量 Agent 效果的过程，是迭代的基础。</td><td><a href="/guide/14-evaluation/why-evals">为什么评估是第一优先级</a></td></tr><tr><td>Golden Dataset / 黄金评估集</td><td>经过人工确认、带有期望结果的核心评估用例集合。</td><td><a href="/guide/14-evaluation/eval-design">评估集与指标设计</a></td></tr><tr><td>LLM-as-Judge / 模型评审</td><td>用大模型按评分标准评判另一个模型的输出。</td><td><a href="/guide/14-evaluation/llm-judge">LLM-as-Judge</a></td></tr><tr><td>Trace / 轨迹</td><td>一次请求从输入到输出的完整执行记录，包括每次模型调用和工具调用。</td><td><a href="/guide/14-evaluation/observability">轨迹追踪与可观测性</a></td></tr><tr><td>Span / 跨度</td><td>轨迹中的单个步骤，比如一次模型调用或一次工具执行。</td><td><a href="/guide/14-evaluation/observability">轨迹追踪与可观测性</a></td></tr><tr><td>Regression Testing / 回归测试</td><td>每次修改后重新运行评估集，确认原有能力没有退化。</td><td><a href="/guide/14-evaluation/regression">回归测试与持续评估</a></td></tr><tr><td>Prompt Injection / 提示词注入</td><td>通过构造输入或外部内容，让模型执行攻击者意图的攻击方式。</td><td><a href="/guide/15-production/prompt-injection">Prompt 注入与防护</a></td></tr><tr><td>Indirect Prompt Injection / 间接提示词注入</td><td>恶意指令藏在网页、文档、工具结果等外部内容中，被 Agent 读取后生效。</td><td><a href="/guide/15-production/prompt-injection">Prompt 注入与防护</a></td></tr><tr><td>Jailbreak / 越狱</td><td>诱导模型绕过安全限制、输出被禁止内容的攻击。</td><td><a href="/guide/15-production/guardrails">护栏与内容安全</a></td></tr><tr><td>HITL (Human-in-the-Loop) / 人在环路</td><td>在关键步骤引入人工审核或确认的设计。</td><td><a href="/guide/15-production/permissions-hitl">权限控制与人在环路</a></td></tr><tr><td>Least Privilege / 最小权限原则</td><td>只授予完成任务所必需的最小权限。</td><td><a href="/guide/15-production/permissions-hitl">权限控制与人在环路</a></td></tr><tr><td>Guardrails / 护栏</td><td>对输入、输出和行为进行检查和限制的机制，如内容审核、格式校验、敏感信息过滤。</td><td><a href="/guide/15-production/guardrails">护栏与内容安全</a></td></tr><tr><td>Model Routing / 模型路由</td><td>根据任务难度或类型把请求分配给不同模型，平衡效果与成本。</td><td><a href="/guide/15-production/cost-optimization">成本与延迟优化</a></td></tr><tr><td>Fallback / 降级</td><td>主模型或服务不可用时切换到备用方案。</td><td><a href="/guide/15-production/deployment">部署、监控与运维</a></td></tr></tbody></table><p>找不到的术语，可以在页面顶部搜索，或者查看 <a href="/guide/">知识体系</a> 中的对应模块。</p>',21)])])}const m=d(o,[["render",i]]);export{c as __pageData,m as default};
